def simulate_plant(products, ledger, capacity_map):
    current_stock = {p: products[p]['opening_stock'] for p in products}
    queue = [] # list of {'day': d, 'product': p, 'remaining': r, 'initial': i}

    production = {}
    all_orders = []
    for r in ledger:
        production[(r['day'], r['product'])] = r['produced']
        if r['ordered'] > 0:
            all_orders.append({'day': r['day'], 'product': r['product'], 'quantity': r['ordered']})

    daily_stock = {} 
    daily_backordered = {} 
    capacity_reached_days = set()
    shipped_in_full_on_day_placed = set() 

    for day in range(71, 85):
        cap = capacity_map.get(day, 300000)
        remaining_cap = cap

        for p in products:
            current_stock[p] += production.get((day, p), 0)

        for order in all_orders:
            if order['day'] == day:
                queue.append({
                    'day': order['day'], 
                    'product': order['product'], 
                    'remaining': order['quantity'], 
                    'initial': order['quantity']
                })

        tried_today = set()
        while True:
            open_orders = [i for i, o in enumerate(queue) if o['remaining'] > 0 and i not in tried_today]
            if not open_orders:
                break

            min_day = min(queue[i]['day'] for i in open_orders)
            candidates_idx = [i for i in open_orders if queue[i]['day'] == min_day]
            candidates_idx.sort(key=lambda i: (queue[i]['remaining'], queue[i]['product']))

            best_idx = candidates_idx[0]
            order = queue[best_idx]
            p = order['product']
            w = products[p]['weight']

            can_ship_by_stock = min(order['remaining'], current_stock[p])
            can_ship_by_cap = int(remaining_cap // w)

            units_to_ship = min(can_ship_by_stock, can_ship_by_cap)

            if units_to_ship > 0:
                order['remaining'] -= units_to_ship
                current_stock[p] -= units_to_ship
                remaining_cap -= units_to_ship * w

                if order['remaining'] == 0:
                    if order['day'] == day:
                        shipped_in_full_on_day_placed.add((day, p))

            if units_to_ship < can_ship_by_stock:
                capacity_reached_days.add(day)

            tried_today.add(best_idx)

        daily_stock[day] = {p: current_stock[p] for p in products}
        daily_backordered[day] = {}
        for p in products:
            back = sum(o['remaining'] for o in queue if o['product'] == p)
            daily_backordered[day][p] = back

    return daily_stock, daily_backordered, capacity_reached_days, shipped_in_full_on_day_placed

